function DashboardView({ profile, workoutsData, completedIds, completedWorkoutIds, weekSlots, weekCompletions, totalWeekCompletions, onSelectWorkout }) {
  const belt = BELT_LEVELS.find(b => b.id === profile.belt_id) || BELT_LEVELS[0];
  const bw = workoutsData || [];
  const hour = new Date().getHours();
  const greeting = hour < 12 ? "Good morning" : hour < 18 ? "Good afternoon" : "Good evening";
  // Demo video popup — show only on first dashboard visit
  const storageKey = "levelupball_demo_seen_" + profile.id;
  const [showDemo, setShowDemo] = useState(() => {
    try { return !sessionStorage.getItem(storageKey) && !localStorage.getItem(storageKey); } catch(e) { return false; }
  });
  const dismissDemo = () => {
    setShowDemo(false);
    try { localStorage.setItem(storageKey, "1"); sessionStorage.setItem(storageKey, "1"); } catch(e) {}
  };
  // XP system - based on week completions
  const wDone = totalWeekCompletions || 0;
  const xpPerWorkout = belt.xpPerWorkout || 200;
  const xpGoal = belt.xpGoal || 1000;
  const currentXp = wDone * xpPerWorkout;
  const xpPct = xpGoal > 0 ? Math.min(100, Math.round((currentXp / xpGoal) * 100)) : 100;
  const xpUnlocked = currentXp >= xpGoal;
  // #10 Next workout = first incomplete
  const nextSlot = (weekSlots || []).find(s => !s.isWeekCompleted);
  const nextWorkout = nextSlot || null;
  return (
    <div className="fade-in">
      {/* First-time demo video popup */}
      {showDemo && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.85)", zIndex: 9999, display: "flex", alignItems: "center", justifyContent: "center", padding: 20, backdropFilter: "blur(6px)" }} onClick={dismissDemo}>
          <div className="fade-in" style={{ width: "100%", maxWidth: 640, background: C.surface, borderRadius: 24, border: `1px solid ${C.border}`, overflow: "hidden" }} onClick={e => e.stopPropagation()}>
            <div style={{ padding: "24px 24px 0" }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
                <div>
                  <h2 style={{ fontFamily: DISPLAY, fontSize: 22, fontWeight: 800, color: "#fff" }}>Welcome to LevelUpBall! 🏀</h2>
                  <p style={{ color: C.textDim, fontSize: 13, marginTop: 4 }}>Watch this quick demo to get started</p>
                </div>
                <button onClick={dismissDemo} style={{ background: C.surfaceHover, border: `1px solid ${C.border}`, borderRadius: 10, width: 36, height: 36, display: "flex", alignItems: "center", justifyContent: "center", color: C.textMuted, fontSize: 18, cursor: "pointer", flexShrink: 0 }}>{"\u2715"}</button>
              </div>
            </div>
            <div style={{ padding: "0 24px" }}>
              <div style={{ borderRadius: 16, overflow: "hidden", border: `1px solid ${C.border}` }}>
                <VideoPlayer url="https://youtu.be/3N6uZ7Fwqmo" />
              </div>
            </div>
            <div style={{ padding: "20px 24px 24px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
              <p style={{ fontSize: 12, color: C.textDim }}>You can rewatch this anytime in the <strong style={{ color: C.accent }}>Resources</strong> tab.</p>
              <button onClick={dismissDemo} style={{ background: `linear-gradient(135deg, ${belt.color}, ${belt.color}cc)`, color: belt.id === "white" ? "#111" : "#fff", border: "none", borderRadius: 12, padding: "10px 24px", fontSize: 14, fontWeight: 700, cursor: "pointer", fontFamily: DISPLAY }}>Let's Go!</button>
            </div>
          </div>
        </div>
      )}
      <div style={{ marginBottom: 32 }}>
        <p style={{ color: C.textDim, fontSize: 14, marginBottom: 4 }}>{greeting}</p>
        <h1 style={{ fontFamily: DISPLAY, fontSize: 32, fontWeight: 800, letterSpacing: -0.5 }}>{profile.user_type === "player" ? ((profile.full_name && !profile.full_name.includes("@")) ? profile.full_name.split(" ")[0] : "Player") : "Player"} 👊</h1>
        {(() => { const q = getDailyQuote(); return (
          <div style={{ background: C.surface, borderRadius: 14, padding: "14px 18px", border: `1px solid ${C.border}`, marginTop: 12, display: "flex", alignItems: "flex-start", gap: 10 }}>
            <span style={{ fontSize: 18, flexShrink: 0 }}>🔥</span>
            <div><p style={{ fontSize: 13, color: C.text, fontStyle: "italic", lineHeight: 1.5 }}>"{q.text}"</p><p style={{ fontSize: 11, color: C.textDim, marginTop: 4 }}>— {q.author}</p></div>
          </div>
        ); })()}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 16, marginBottom: 32 }}>
        {/* XP Progress */}
        <div style={{ background: C.surface, borderRadius: 20, padding: 24, border: `1px solid ${C.border}`, position: "relative", overflow: "hidden" }}>
          <div style={{ position: "absolute", top: -20, right: -20, width: 100, height: 100, borderRadius: "50%", background: xpUnlocked ? C.successGlow : C.accentGlow, filter: "blur(30px)" }} />
          <div style={{ position: "relative" }}>
            <p style={{ fontSize: 13, fontWeight: 800, color: "#fff", textTransform: "uppercase", letterSpacing: 1.5, marginBottom: 4, fontFamily: DISPLAY }}>XP to Level Up Test</p>
            {xpUnlocked ? (
              <div><p style={{ fontFamily: DISPLAY, fontSize: 20, fontWeight: 800, color: C.success, lineHeight: 1.2 }}>UNLOCKED! 🔥</p><p style={{ fontSize: 11, color: C.success, marginTop: 4 }}>You can now apply to level up</p></div>
            ) : (
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end" }}>
                <div>
                  <p style={{ fontFamily: DISPLAY, fontSize: 28, fontWeight: 800, lineHeight: 1, color: "#22C55E" }}>{currentXp}<span style={{ fontSize: 14, color: "#22C55E" }}>/{xpGoal} XP</span></p>
                  <p style={{ fontSize: 11, color: C.textDim, marginTop: 4 }}><span style={{ color: "#22C55E", fontWeight: 700 }}>{xpGoal - currentXp} XP</span> until Level Up Test</p>
                </div>
                <ProgressRing percent={xpPct} size={52} color="#22C55E" />
              </div>
            )}
            <div style={{ height: 6, background: C.border, borderRadius: 3, marginTop: 14 }}><div style={{ height: "100%", width: `${xpPct}%`, background: `linear-gradient(90deg, #22C55E, #4ADE80)`, borderRadius: 3, transition: "width 0.8s" }} /></div>
            <p style={{ fontSize: 11, color: C.textDim, marginTop: 6 }}>{wDone} workouts completed · {xpPerWorkout} XP each</p>
          </div>
        </div>
        {/* Belt card */}
        <div style={{ background: C.surface, borderRadius: 20, padding: 24, border: `1px solid ${C.border}` }}>
          <p style={{ fontSize: 12, fontWeight: 500, color: C.textDim, textTransform: "uppercase", letterSpacing: 1, marginBottom: 8 }}>Current Belt</p>
          <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
            <BeltIcon beltId={profile.belt_id} size={52} />
            <div><p style={{ fontFamily: DISPLAY, fontSize: 20, fontWeight: 700 }}>{belt.name}</p><p style={{ fontSize: 13, color: belt.color, fontWeight: 700, fontFamily: DISPLAY }}>Level {belt.level} of 5</p></div>
          </div>
        </div>
        {/* Workouts stat */}
        <div style={{ background: C.surface, borderRadius: 20, padding: 24, border: `1px solid ${C.border}` }}>
          <p style={{ fontSize: 12, fontWeight: 500, color: C.textDim, textTransform: "uppercase", letterSpacing: 1, marginBottom: 8 }}>Workouts</p>
          <p style={{ fontFamily: DISPLAY, fontSize: 32, fontWeight: 800, lineHeight: 1 }}>{wDone}<span style={{ fontSize: 16, color: C.textDim }}>/{(weekSlots || []).length}</span></p>
          <p style={{ fontSize: 12, color: C.textDim, marginTop: 4 }}>+<span style={{ color: "#22C55E", fontWeight: 700 }}>{currentXp} XP</span> earned</p>
        </div>
      </div>
      {/* #10 Next workout — clickable */}
      {nextWorkout && (
        <div>
          <h2 style={{ fontFamily: DISPLAY, fontSize: 18, fontWeight: 700, marginBottom: 14 }}>Up Next</h2>
          <button onClick={() => onSelectWorkout(nextWorkout, nextSlot?.week)} style={{ width: "100%", background: C.surface, border: `1.5px solid ${belt.color}44`, borderRadius: 18, padding: 20, cursor: "pointer", textAlign: "left", display: "flex", alignItems: "center", justifyContent: "space-between", fontFamily: FONTS, transition: "all 0.2s" }} onMouseEnter={e => { e.currentTarget.style.transform = "translateY(-2px)"; e.currentTarget.style.boxShadow = "0 8px 24px rgba(0,0,0,0.3)"; }} onMouseLeave={e => { e.currentTarget.style.transform = ""; e.currentTarget.style.boxShadow = ""; }}>
            <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
              <div style={{ width: 56, height: 56, borderRadius: 16, background: `linear-gradient(135deg, ${belt.color}, ${belt.color}CC)`, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: DISPLAY, fontSize: 20, fontWeight: 800, color: "#fff" }}>{nextSlot?.displayNum || nextWorkout.name.replace("Workout ", "")}</div>
              <div><p style={{ fontFamily: DISPLAY, fontSize: 16, fontWeight: 700, color: C.text }}>Workout {nextSlot?.displayNum || nextWorkout.name.replace("Workout ", "")}</p><p style={{ fontSize: 12, color: C.textDim, marginTop: 4 }}>{(nextWorkout.cats||[]).length} categories · {(nextWorkout.cats||[]).reduce((s,c)=>s+(c.exercises||[]).length,0)} exercises</p></div>
            </div>
            <span style={{ color: belt.color, fontSize: 20 }}>→</span>
          </button>
        </div>
      )}
      {!nextWorkout && bw.length > 0 && (
        <div style={{ background: C.successGlow, borderRadius: 16, padding: 24, textAlign: "center", border: `1px solid ${C.success}33` }}>
          <div style={{ fontSize: 32, marginBottom: 8 }}>🎉</div>
          <p style={{ fontFamily: DISPLAY, fontSize: 16, fontWeight: 700, color: C.success }}>All workouts completed!</p>
        </div>
      )}
    </div>
  );
}
