// STUDENT LAYOUT
// ============================================================
function StudentLayout({ profile, token, onLogout, trialMode }) {
  const [activeTab, setActiveTab] = useState("dashboard");
  const [workoutsData, setWorkoutsData] = useState([]);
  const [completedIds, setCompletedIds] = useState(new Set());
  const [completedWorkoutIds, setCompletedWorkoutIds] = useState(new Set());
  const [weekCompletions, setWeekCompletions] = useState([]);
  const [challengeResults, setChallengeResults] = useState([]);
  const [activeWorkout, setActiveWorkout] = useState(null);
  const [activeWeek, setActiveWeek] = useState(null);
  const [loaded, setLoaded] = useState(false);
  const belt = BELT_LEVELS.find(b => b.id === profile.belt_id) || BELT_LEVELS[0];
  // Build virtual workout slots: flat numbered list with repeating from DB workouts
  const buildWorkoutSlots = () => {
    const bw = workoutsData || [];
    if (bw.length === 0) return [];
    const slots = [];
    const total = belt.totalWorkouts || bw.length;

    if (belt.repeatMap) {
      // Phase-based repeat: e.g. Level 3 has 3A then 3B sections
      belt.repeatMap.forEach(section => {
        const sectionWorkouts = bw.slice(section.start, section.start + section.count);
        if (sectionWorkouts.length === 0) return;
        const sectionStartIdx = slots.length; // mark where this section begins
        if (section.fill) {
          // Repeat until we hit the fill target total
          while (slots.length < section.fill) {
            for (let i = 0; i < sectionWorkouts.length && slots.length < section.fill; i++) {
              const w = sectionWorkouts[i];
              const slotNum = slots.length + 1;
              const isCompleted = weekCompletions.some(wc => wc.workout_id === w.id && wc.week_number === slotNum);
              slots.push({ ...w, week: slotNum, slotIndex: slots.length, isWeekCompleted: isCompleted, originalIndex: section.start + i, displayNum: slotNum, phaseLabel: section.label || null, phaseStart: slots.length === sectionStartIdx });
            }
          }
        } else {
          // Fixed repeat count
          for (let r = 0; r < (section.repeat || 1); r++) {
            for (let i = 0; i < sectionWorkouts.length; i++) {
              const w = sectionWorkouts[i];
              const slotNum = slots.length + 1;
              const isCompleted = weekCompletions.some(wc => wc.workout_id === w.id && wc.week_number === slotNum);
              slots.push({ ...w, week: slotNum, slotIndex: slots.length, isWeekCompleted: isCompleted, originalIndex: section.start + i, displayNum: slotNum, phaseLabel: section.label || null, phaseStart: slots.length === sectionStartIdx });
            }
          }
        }
        // Mark the first slot of this section
        if (slots.length > sectionStartIdx) slots[sectionStartIdx].phaseStart = true;
      });
    } else {
      // Simple cycling: e.g. Level 1 has 3 workouts cycling to 21
      for (let n = 0; n < total; n++) {
        const w = bw[n % bw.length];
        const slotNum = n + 1;
        const isCompleted = weekCompletions.some(wc => wc.workout_id === w.id && wc.week_number === slotNum);
        slots.push({ ...w, week: slotNum, slotIndex: n, isWeekCompleted: isCompleted, originalIndex: n % bw.length, displayNum: slotNum });
      }
    }
    return slots;
  };
  const weekSlots = buildWorkoutSlots();
  const totalWeekCompletions = weekCompletions.length;
  useEffect(() => {
    (async () => {
      // Load all data in parallel for speed
      try {
        if (trialMode) {
          // Trial mode: load workouts only via public access
          try {
            const wks = await supabase.from("workouts").select("*", `&belt_id=eq.${profile.belt_id}&order=sort_order`);
            const allCats = await Promise.all(wks.map(w => supabase.from("categories").select("*", `&workout_id=eq.${w.id}&order=sort_order`)));
            wks.forEach((w, i) => w.cats = allCats[i]);
            const allCatIds = wks.flatMap(w => (w.cats || []).map(c => c.id));
            const allExs = await Promise.all(allCatIds.map(cid => supabase.from("exercises").select("*", `&category_id=eq.${cid}&order=sort_order`)));
            let idx = 0;
            wks.forEach(w => (w.cats || []).forEach(c => { c.exercises = allExs[idx++]; }));
            setWorkoutsData(wks);
          } catch(e) { console.error("Trial load error:", e); }
          setLoaded(true);
          return;
        }
        const [wks, comps, wComps, weekComps, cResults] = await Promise.all([
          supabase.from("workouts")._token(token).select("*", `&belt_id=eq.${profile.belt_id}&order=sort_order`),
          supabase.from("completed_exercises")._token(token).select("exercise_id", `&student_id=eq.${profile.id}`).catch(() => []),
          supabase.from("completed_workouts")._token(token).select("workout_id", `&student_id=eq.${profile.id}`).catch(() => []),
          supabase.from("workout_week_completions")._token(token).select("*", `&student_id=eq.${profile.id}`).catch(() => []),
          supabase.from("challenge_results")._token(token).select("*", `&student_id=eq.${profile.id}`).catch(() => []),
        ]);
        // Load all categories in parallel
        const allCats = await Promise.all(wks.map(w => supabase.from("categories")._token(token).select("*", `&workout_id=eq.${w.id}&order=sort_order`)));
        wks.forEach((w, i) => w.cats = allCats[i]);
        // Load all exercises in parallel
        const allCatIds = wks.flatMap(w => (w.cats || []).map(c => c.id));
        const allExercises = await Promise.all(allCatIds.map(cid => supabase.from("exercises")._token(token).select("*", `&category_id=eq.${cid}&order=sort_order`)));
        let exIdx = 0;
        wks.forEach(w => (w.cats || []).forEach(c => { c.exercises = allExercises[exIdx++]; }));
        setWorkoutsData(wks);
        setCompletedIds(new Set(comps.map(c => c.exercise_id)));
        setCompletedWorkoutIds(new Set(wComps.map(c => c.workout_id)));
        setWeekCompletions(weekComps);
        setChallengeResults(cResults);
      } catch (e) { console.error("Error loading:", e); }
      setLoaded(true);
    })();
  }, [token, profile]);
  const toggleComplete = async (exerciseId) => {
    const ns = new Set(completedIds);
    if (ns.has(exerciseId)) { ns.delete(exerciseId); setCompletedIds(ns); try { await supabase.from("completed_exercises")._token(token).delete({ student_id: profile.id, exercise_id: exerciseId }); } catch(e){} }
    else { ns.add(exerciseId); setCompletedIds(ns); try { await supabase.from("completed_exercises")._token(token).insert({ student_id: profile.id, exercise_id: exerciseId }); } catch(e){} }
  };
  const completeWeekWorkout = async (workoutId, weekNum) => {
    try {
      await supabase.from("workout_week_completions")._token(token).insert({ student_id: profile.id, workout_id: workoutId, week_number: weekNum });
      setWeekCompletions([...weekCompletions, { workout_id: workoutId, week_number: weekNum }]);
      // Also mark in old system for backward compat
      if (!completedWorkoutIds.has(workoutId)) {
        try { await supabase.from("completed_workouts")._token(token).insert({ student_id: profile.id, workout_id: workoutId }); } catch(e){}
        setCompletedWorkoutIds(new Set([...completedWorkoutIds, workoutId]));
      }
    } catch(e) { console.error(e); }
  };
  const saveChallengeResult = async (exerciseId, workoutId, reps, exerciseName) => {
    try {
      await supabase.from("challenge_results")._token(token).upsert({ student_id: profile.id, exercise_id: exerciseId, workout_id: workoutId, week_number: activeWeek || 1, reps_completed: reps, exercise_name: exerciseName || "" });
      const updated = await supabase.from("challenge_results")._token(token).select("*", `&student_id=eq.${profile.id}`);
      setChallengeResults(updated);
    } catch (e) { console.error(e); }
  };
  if (!loaded) return <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center" }}><img src={LOGO_SM} alt="" style={{ width: 100, height: 100, animation: "pulse 1.5s infinite" }} /></div>;
  return (
    <>
      <style>{`
        @media (max-width: 768px) { .sidebar-desktop { display: none !important; } .mobile-nav { display: flex !important; } .main-content { padding-bottom: 80px !important; } .mobile-subtabs { display: block !important; } }
        @media (min-width: 769px) { .sidebar-desktop { display: flex !important; } .mobile-nav { display: none !important; } }
      `}</style>
      {trialMode && (
        <div style={{ background: "linear-gradient(135deg, #FF6D00, #EA580C)", padding: "10px 20px", textAlign: "center", position: "sticky", top: 0, zIndex: 200, display: "flex", alignItems: "center", justifyContent: "center", gap: 12 }}>
          <span style={{ fontSize: 14 }}>🔥</span>
          <span style={{ fontFamily: DISPLAY, fontSize: 13, fontWeight: 700, color: "#fff" }}>You're previewing LevelUpBall! Get the full program to unlock all workouts and features.</span>
          <button onClick={() => openStripeCheckout("", "")} style={{ background: "#fff", color: "#EA580C", fontFamily: DISPLAY, fontSize: 11, fontWeight: 700, padding: "6px 16px", borderRadius: 8, border: "none", cursor: "pointer", letterSpacing: 0.5 }}>GET FULL ACCESS</button>
        </div>
      )}
      {!trialMode && profile?.trial_expires_at && <TrialCountdownBanner profile={profile} />}
      <div style={{ display: "flex", minHeight: "100vh" }}>
        <Sidebar activeTab={activeWorkout ? "workouts" : activeTab} setActiveTab={(t) => { setActiveTab(t); setActiveWorkout(null); }} profile={profile} onLogout={onLogout} trialMode={trialMode} />
        <main className="main-content" style={{ flex: 1, padding: "32px", maxWidth: 960, margin: "0 auto", width: "100%" }}>
          {activeWorkout ? (
            <WorkoutView workout={activeWorkout} weekNum={activeWeek} onBack={() => { setActiveWorkout(null); setActiveWeek(null); }} completedIds={completedIds} onToggle={toggleComplete} token={token} profile={profile} completedWorkoutIds={completedWorkoutIds} weekCompletions={weekCompletions} onCompleteWorkout={completeWeekWorkout} challengeResults={challengeResults} onSaveChallengeResult={saveChallengeResult} />
          ) : activeTab === "dashboard" ? (
            <DashboardView profile={profile} workoutsData={workoutsData} completedIds={completedIds} completedWorkoutIds={completedWorkoutIds} weekSlots={weekSlots} weekCompletions={weekCompletions} totalWeekCompletions={totalWeekCompletions} onSelectWorkout={(w, week) => { setActiveWorkout(w); setActiveWeek(week); setActiveTab("workouts"); }} />
          ) : (activeTab === "workouts" || activeTab === "quick") ? (
            <div>
              <div className="mobile-subtabs" style={{ display: "none", marginBottom: 20 }}>
                <div style={{ display: "flex", background: C.surface, borderRadius: 14, border: `1px solid ${C.border}`, padding: 3 }}>
                  <button onClick={() => setActiveTab("workouts")} style={{ flex: 1, padding: "10px 0", borderRadius: 11, border: "none", background: activeTab === "workouts" ? C.accent : "transparent", color: activeTab === "workouts" ? "#fff" : C.textDim, fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: FONTS, transition: "all 0.15s" }}>🏀 Workouts</button>
                  <button onClick={() => setActiveTab("quick")} style={{ flex: 1, padding: "10px 0", borderRadius: 11, border: "none", background: activeTab === "quick" ? C.accent : "transparent", color: activeTab === "quick" ? "#fff" : C.textDim, fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: FONTS, transition: "all 0.15s" }}>⏱️ Quick Sessions</button>
                </div>
              </div>
              {activeTab === "workouts" ? (
                <WorkoutsList workoutsData={workoutsData} completedIds={completedIds} completedWorkoutIds={completedWorkoutIds} weekSlots={weekSlots} weekCompletions={weekCompletions} onSelect={(w, week) => { setActiveWorkout(w); setActiveWeek(week); }} profile={profile} trialMode={trialMode} />
              ) : (
                <QuickSessions token={token} profile={profile} trialMode={trialMode} challengeResults={challengeResults} onSaveChallengeResult={saveChallengeResult} />
              )}
            </div>
          ) : activeTab === "challenges" ? (
            <StudentChallenges token={token} profile={profile} trialMode={trialMode} />
          ) : activeTab === "resources" ? (
            <StudentResources token={token} profile={profile} trialMode={trialMode} />
          ) : activeTab === "levelup" ? (
            <StudentLevelUp token={token} profile={profile} completedWorkoutIds={completedWorkoutIds} workoutsData={workoutsData} totalWeekCompletions={totalWeekCompletions} trialMode={trialMode} />
          ) : activeTab === "messages" ? (
            <StudentMessages token={token} profile={profile} trialMode={trialMode} />
          ) : null}
        </main>
      </div>
    </>
  );
}
